package main

import "fmt"

type Point struct{ X, Y int }

// String satisfies fmt.Stringer; %v and %s will call it
func (p Point) String() string {
	return fmt.Sprintf("(%d, %d)", p.X, p.Y)
}

func main() {
	p := Point{3, 4}
	fmt.Printf("%v\n", p) // (3, 4)
}

