package solution

import "fmt"

func FormatPrice(cents int) string {
	dollars := cents / 100        // whole dollars
	rem := cents % 100            // leftover cents
	if rem < 0 {                  // keep cents non-negative for display
		rem = -rem
	}
	// %02d pads the cents to two digits (e.g. 5 -> 05)
	return fmt.Sprintf("$%d.%02d", dollars, rem)
}

