func Table(rows [][]string) string {
	if len(rows) == 0 {
		return ""
	}
	widths := make([]int, len(rows[0])) // max width per column
	for _, row := range rows {
		for c, cell := range row {
			if len(cell) > widths[c] {
				widths[c] = len(cell)
			}
		}
	}
	var b strings.Builder
	for _, row := range rows {
		for c, cell := range row {
			// %-*s left-aligns cell in widths[c] columns
			fmt.Fprintf(&b, "%-*s ", widths[c], cell)
		}
		b.WriteByte('\n')
	}
	return b.String()
}
